// Hot reload (r) picks up:
// ✅ build() bodies, widget trees, styles, layout
// ✅ new widgets, new methods, changed method bodies

// Hot reload does NOT pick up:
// ❌ main() and runApp()
// ❌ initState bodies and anything else that already ran at startup
// ❌ global / static field initializers
// ❌ class shape changes (added fields, changed hierarchy)

// Full restart (stop, then flutter run) is required for:
// ❌ native code (Kotlin/Swift), added or removed plugins
// ❌ pubspec.yaml dependency and asset changes
// ❌ build configuration and flavors

// flutter CLI:
// flutter run           → start in debug (JIT — hot reload available)
// r                     → hot reload
// R                     → hot restart
// q                     → quit
// flutter run --release → AOT build, no hot reload

class ResponsivePage extends StatelessWidget {
  const ResponsivePage({super.key});

  @override
  Widget build(BuildContext context) {
    // Screen information
    final size = MediaQuery.sizeOf(context);
    final padding = MediaQuery.paddingOf(context);  // safe area
    final textScale = MediaQuery.textScalerOf(context);
    final orientation = MediaQuery.orientationOf(context);
    final isDark = MediaQuery.platformBrightnessOf(context) == Brightness.dark;

    final isTablet = size.width >= 600;
    final isDesktop = size.width >= 1200;

    return Scaffold(
      body: SafeArea(  // respects status bar + notch
        child: LayoutBuilder(  // ✅ prefer over MediaQuery for layouts
          builder: (context, constraints) {
            if (constraints.maxWidth >= 1200) {
              return _DesktopLayout();
            } else if (constraints.maxWidth >= 600) {
              return _TabletLayout();
            }
            return _MobileLayout();
          },
        ),
      ),
    );
  }
}

// Responsive grid
class ResponsiveGrid extends StatelessWidget {
  final List<Widget> items;
  const ResponsiveGrid({super.key, required this.items});

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) {
        final crossAxisCount = switch (constraints.maxWidth) {
          >= 1200 => 4,
          >= 800  => 3,
          >= 600  => 2,
          _       => 1,
        };
        return GridView.builder(
          gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
            crossAxisCount: crossAxisCount,
            crossAxisSpacing: 16,
            mainAxisSpacing: 16,
          ),
          itemCount: items.length,
          itemBuilder: (_, i) => items[i],
        );
      },
    );
  }
}

// ── Problem: Without keys ──────────────────
class StatefulTile extends StatefulWidget {
  final String title;
  const StatefulTile(this.title, {super.key});

  @override State<StatefulTile> createState() => _StatefulTileState();
}

class _StatefulTileState extends State<StatefulTile> {
  bool selected = false;

  @override Widget build(BuildContext context) {
    return ListTile(
      title: Text(widget.title),
      selected: selected,
      onTap: () => setState(() => selected = !selected),
    );
  }
}

class BadList extends StatefulWidget {
  @override State<BadList> createState() => _BadListState();
}

class _BadListState extends State<BadList> {
  List<String> items = ['A', 'B', 'C'];

  void removeFirst() {
    setState(() => items.removeAt(0));
  }

  @override Widget build(BuildContext context) {
    return Column(
      children: [
        ...items.map((item) => StatefulTile(item)), // ✗ No keys
        ElevatedButton(
          onPressed: removeFirst,
          child: Text('Remove First'),
        ),
      ],
    );
  }
}

// Problem: If you select 'B', then remove 'A',
// the selection stays on second position (now 'C')
// because Flutter matches widgets by type and position

// ── Solution: With keys ────────────────────
class _GoodListState extends State<GoodList> {
  List<String> items = ['A', 'B', 'C'];

  void removeFirst() {
    setState(() => items.removeAt(0));
  }

  @override Widget build(BuildContext context) {
    return Column(
      children: [
        ...items.map((item) =>
          StatefulTile(item, key: ValueKey(item)) // ✓ With keys
        ),
        ElevatedButton(
          onPressed: removeFirst,
          child: Text('Remove First'),
        ),
      ],
    );
  }
}

// Now Flutter correctly tracks each widget by its key

